        x = y;
        y = r;
    }

    a /= x;
    b /= x;

    bool swapped = false;
    if (A < B) {
        swap(A, B);
        swapped = true;
    }
    if (a < b) {
        swap(a, b);
    }

    unsigned long long scale = min(A / a, B / b);
    A = a * scale;
    B = b * scale;

    if (swapped) {
        swap(A, B);
    }

    cout << A << ' ' << B;
    return 0;
}

